import argparse,hashlib,json,time,sys
from datetime import date
from pathlib import Path

HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[1]
def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,d):
 with p.open('x') as f:json.dump(d,f,ensure_ascii=False,indent=2,allow_nan=False)

def prepare(out,request,company,cutoff,requested_epoch,stock=None):
 if not isinstance(requested_epoch,(int,float)) or not requested_epoch<=time.time():raise ValueError('Actual original request time required')
 if time.time()-requested_epoch>=585:raise ValueError('Request work budget already expired')
 if not request.strip() or not company.strip():raise ValueError('Explicit original request and entity required')
 date.fromisoformat(cutoff)
 if stock is not None and (len(stock)!=6 or not stock.isdigit()):raise ValueError('Six-digit listed identity required')
