 definitions+=[ROOT/'protected/evaluations/valuation-v1.json',*[profile/n for n in ('adoption.json','approval.json','candidate-reviewer-config.json','candidate-five-axis-anchors.md','candidate-reviewer-instructions.md')]]
 definitions+=[ROOT/'libraries/personas'/name/n for name in persona_ids.values() for n in ('component.json','ROLE.md')]
 components={str(p.relative_to(ROOT)):digest(p) for p in [HERE/'coldrun.py',HERE/'dispatch.py',HERE/'controller.js',HERE/'model.py',HERE/'input.schema.json',HERE/'report.py',HERE/'narrative.py',HERE/'workbook.py',HERE/'vendor/manifest.json',ROOT/'pr/report_path.py',*definitions]}
