 # Pin all local execution dependencies and declared design assets before dispatch.
 for folder in (HERE,ROOT/'pr'):
  for path in folder.glob('*'):
   if path.is_file() and path.suffix in {'.py','.json','.js'}:components[str(path.relative_to(ROOT))]=digest(path)
 vendor=HERE/'vendor'
 for name,expected in json.loads((vendor/'manifest.json').read_text())['files'].items():
  path=(vendor/name).resolve()
  if not path.is_relative_to(vendor.resolve()) or digest(path)!=expected:raise ValueError('Declared design dependency changed')
  components[str(path.relative_to(ROOT))]=expected
 write(out/'component-snapshot.json',{'status':'provisional','components':components,'root':str(ROOT),'created_epoch':time.time()})
 write(out/'mandate.json',mandate)
 base=f'Current task: {request}\nEntity: {company}. Information cutoff/valuation date: {cutoff}. Original request epoch: {requested_epoch}. Attempt directory: {out}. This is full valuation, not reverse DCF or an arbitrary numerical illustration. Budget includes company research; work stops at original request+585 seconds and delivery at+600. Inherit host model, fresh task session, no prior company report/model-result reading. Keep tool outputs short, full evidence on disk. Existing executive report specimen only; no new design or aesthetic review. Do not change protected criteria, source code, prior attempts or active release. '
